# Executed inside build_index.py (uses rep()). Edits the final "Existing-bot linking and isolated synthetic card rails" script.
# 8a. dialog shell: step header, close X, labelled title; backdrop click and Escape now clear the poll timer too.
rep("""function shell(html){$('#modal .box').innerHTML='<div class="cw">'+html+'<button class="btn" id="linkclose" style="margin-top:16px">Close</button></div>';$('#linkclose').onclick=()=>{clearInterval(timer);$('#modal').classList.remove('on')};$('#modal').classList.add('on')}""",
"""function shell(html){const st=W.step||0,steps=W.reconnect?['Reconnect']:['Choose bot','Name it','Authorize'];html=html.replace('<h3>','<h3 id="cw-title">');$('#modal').setAttribute('aria-labelledby','cw-title');$('#modal').removeAttribute('aria-label');
$('#modal .box').innerHTML='<div class="cw" data-step="'+st+'"'+(W.reconnect?' data-mode="reconnect"':'')+'><div class="cw-head"><ol class="cw-steps" aria-label="Progress">'+steps.map((s,i)=>'<li class="'+(W.reconnect?'on':i<st?'done':i===st?'on':'')+'"'+((W.reconnect||i===st)?' aria-current="step"':'')+'><span>'+(W.reconnect?'↻':i+1)+'</span>'+s+'</li>').join('')+'</ol><button class="cw-x" type="button" aria-label="Close" id="cwx">×</button></div>'+html+'<button class="btn" id="linkclose" style="margin-top:16px">Close</button></div>';
$('#linkclose').onclick=()=>{clearInterval(timer);window.__linkWaiting=null;$('#modal').classList.remove('on');if(typeof render==='function')render()};$('#cwx').onclick=()=>$('#linkclose').click();
$('#modal').onclick=e=>{if(e.target===$('#modal')&&$('#linkclose'))$('#linkclose').click()};$('#modal').classList.add('on');requestAnimationFrame(()=>{const f=$('#modal .cw h3');if(f){f.tabIndex=-1;f.focus()}})}""")
# 8b. step 0: provider identity marks
rep("""P.map(p=>'<button class="btn opt" data-link="'+p[0]+'"><b>'+p[1]+'</b>""",
    """P.map(p=>'<button class="btn opt" data-link="'+p[0]+'"><span class="av" aria-hidden="true" style="--av:'+({grok:'#121212',instinct:'#C8361D',muse:'#2F5DA8'}[p[0]]||'#5C5C57')+'">'+initialsOf(p[1])+'</span><b>'+p[1]+'</b>""")
# 8c. step 2: title for reconnect, paired actions (owner decision: Install in Cursor is primary and first; Copy setup message secondary at equal size), live status region
rep("""shell('<h3>Authorize '+esc(W.agent.name)+'</h3><p>'+guidance+'</p>""",
    """window.__linkWaiting=W.agent.id;{const _wa=typeof byId!=='undefined'&&byId[W.agent.id];if(_wa){_wa._fig='';paint(_wa)}}shell((W.reconnect?'<h3>Reconnect '+esc(W.agent.name)+'</h3><div class="pres-banner" data-presence="reconnect" id="reconnectnote">'+presenceIcon('reconnect')+'<div><b>Reconnect needed</b><p>'+esc(W.agent.name)+' lost its authorization'+(W.reason==='refresh_replay'?' (its renewal token was reused)':W.reason==='persistent_grant_missing'?' (its saved grant is missing)':'')+'. Run the same connection again in this bot and authorize it. This reconnects the existing bot; nothing new is created.</p></div></div>':'<h3>Authorize '+esc(W.agent.name)+'</h3>')+'<p>'+guidance+'</p>""")
rep("""<a class="btn pri" id="cursorinstall">Install in Cursor</a> <button class="btn pri" id="copysetup">Copy setup message</button> <button class="btn" id="copylink">Copy connector address</button>""",
    """<div class="cw-actions" role="group" aria-label="Connect this bot"><a class="btn pri" id="cursorinstall"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 1.8 13.6 5v6L8 14.2 2.4 11V5z" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M8 1.8V8l5.6 3M8 8l-5.6 3" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>Install in Cursor</a><button class="btn" id="copysetup"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><rect x="5" y="5" width="8.5" height="8.5" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M3 10.5V2.5h8" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>Copy setup message</button></div><button class="btn ghost sm" id="copylink">Copy connector address</button>""")
rep("""<div class="card" id="linkstatus" style="padding:14px">Waiting for your bot. No live connection confirmed yet.</div>""",
    """<div class="card" id="linkstatus" role="status" aria-live="polite" data-presence="'+(W.reconnect?'reconnect':'waiting')+'">'+(W.reconnect?presenceIcon('reconnect')+'<b>Reconnect needed.</b> Waiting for '+esc(W.agent.name)+' to authorize again.':presenceIcon('waiting')+'Waiting for your bot. No live connection confirmed yet.')+'</div>""")
# 8d. poll: a stale heartbeat never reads as Connected; reconnect clears only when the grant is active again
rep("""const a=LS?.agents.find(a=>a.id===W.agent.id);if(a?.lastSeen){$('#linkstatus').innerHTML='<b>Connected: '+esc(a.name)+'</b><p>Your bot reported to '+BRAND.name+' at '+esc(new Date(a.lastSeen).toLocaleTimeString())+'.</p>';clearInterval(timer)}},4000)}""",
    """const a=LS?.agents.find(a=>a.id===W.agent.id);const pr=presenceOf(a);if(a?.lastSeen&&pr==='connected'&&(!W.reconnect||a.connection?.status==='active')){$('#linkstatus').dataset.presence='connected';$('#linkstatus').innerHTML=presenceIcon('connected')+'<b>Connected: '+esc(a.name)+'</b><p>Your bot reported to '+BRAND.name+' at '+esc(new Date(a.lastSeen).toLocaleTimeString())+'.</p>';window.__linkWaiting=null;clearInterval(timer)}else if(pr==='reconnect'&&!W.reconnect){$('#linkstatus').dataset.presence='reconnect';$('#linkstatus').innerHTML=presenceIcon('reconnect')+'<b>Reconnect needed.</b> The authorization for '+esc(a.name)+' dropped. Run the connection again.'}},4000)}""")
# 8e. Reconnect entry point: reopens the connect flow (step 2) for the EXISTING bot. No new bot is created.
rep("""openAdd=function(){clearInterval(timer);W={step:0,preset:'balanced'};draw()};$('#addb').onclick=openAdd;""",
    """openAdd=function(){clearInterval(timer);W={step:0,preset:'balanced'};draw()};$('#addb').onclick=openAdd;
window.reconnectBot=function(id){const d=(LS&&LS.agents||[]).find(x=>x.id===id);if(!d)return;clearInterval(timer);if(typeof closeDr==='function')closeDr();const pid=(d.providerId||d.provider||'').toLowerCase();const hit=P.find(p=>p[0]===pid);
 /* TODO-wire: POST d.connection.reconnectEndpoint needs the CLIENT's client_id/redirect_uri/code_challenge (409 client_reconnect_required without them), so the owner UI re-runs the bot-side connect instead. */
 W={step:2,p:hit?hit[0]:pid,label:hit?hit[1]:(d.providerName||d.provider||'assistant'),agent:{id:d.id,name:d.name},reconnect:true,reason:d.connection&&d.connection.reason};draw()};""")
# 8f. card sandbox: semantic classes, labels, tighter section headings (ids and handlers unchanged)
rep("""view.innerHTML='<h3>Card sandbox</h3><div class="card" style="padding:16px;margin-bottom:16px"><b>SYNTHETIC ONLY. No money moves.</b>""",
    """view.innerHTML='<h3>Card sandbox</h3><div class="card synth" role="note"><b>SYNTHETIC ONLY. No money moves.</b>""")
rep("""<div class="grid"><div class="card" style="padding:16px"><h4>Demo a bot spend proposal</h4>""", """<div class="grid sbx"><div class="card"><h4>Demo a bot spend proposal</h4>""")
rep("""<select class="t" id="cardbot">""", """<label class="fl" for="cardbot">Bot</label><select class="t" id="cardbot">""")
rep("""<input class="t" id="cardmerchant" """, """<label class="fl" for="cardmerchant">Merchant</label><input class="t" id="cardmerchant" """)
rep("""<input class="t" id="cardamount" """, """<label class="fl" for="cardamount">Exact USD total</label><input class="t" id="cardamount" """)
rep("""<input class="t" id="cardpurpose" """, """<label class="fl" for="cardpurpose">Purpose</label><input class="t" id="cardpurpose" """)
rep("""<div class="card" style="padding:16px"><h4>Per-bot daily caps (UTC)</h4>'+D.bots.map(b=>'<div style="margin-bottom:12px"><b>'+esc(b.name)+'</b><p>'+usd(b.simulatedTodayCents)+' simulated today / '+usd(b.dailyLimitCents)+' cap</p><input class="t" type="number" min="0" step="0.01" id="cap-'+b.id+'" """,
    """<div class="card"><h4>Per-bot daily caps (UTC)</h4>'+D.bots.map(b=>'<div class="caprow"><b>'+esc(b.name)+'</b><p>'+usd(b.simulatedTodayCents)+' simulated today / '+usd(b.dailyLimitCents)+' cap</p><input class="t" type="number" min="0" step="0.01" aria-label="Daily cap for '+esc(b.name)+' in USD" id="cap-'+b.id+'" """)
rep("""<h3>Decisions</h3>'+D.proposals.map(q=>'<div class="card" style="padding:16px;margin-bottom:12px">""", """<h3 class="sbx-h">Decisions</h3>'+D.proposals.map(q=>'<div class="card sbx-dec">""")
rep("""'<h3>Synthetic ledger</h3>'+D.ledger.map(l=>'<div class="card" style="padding:12px;margin-bottom:8px">""", """'<h3 class="sbx-h">Synthetic ledger</h3>'+D.ledger.map(l=>'<div class="card sbx-led">""")
